-- Morfofunción: Órganos de los sentidos. Reejecutable; conserva material y progreso existentes.
BEGIN;
LOCK TABLE public.flashcards, public.banco_preguntas IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE morfo_incoming ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset('[{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué significa transducción sensitiva?","OPCION_A":"Conversión de un estímulo en una señal celular","OPCION_B":"Transporte del estímulo sin modificarlo hasta la corteza","OPCION_C":"Conversión de una neurona en una célula muscular","OPCION_D":"Producción de anticuerpos por un receptor","RESPUESTA_CORRECTA":"A","EXPLICACION":"La transducción transforma energía del estímulo en cambios eléctricos o químicos del receptor.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué característica tiene el potencial receptor?","OPCION_A":"Tiene siempre amplitud idéntica sin importar el estímulo","OPCION_B":"Es graduado según la estimulación","OPCION_C":"Solo existe en neuronas motoras","OPCION_D":"Es necesariamente una contracción muscular","RESPUESTA_CORRECTA":"B","EXPLICACION":"El potencial receptor cambia de magnitud; los potenciales de acción de una fibra se codifican principalmente por frecuencia.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué plantea el código de línea marcada?","OPCION_A":"Toda fibra transmite indistintamente cualquier modalidad","OPCION_B":"El tamaño del potencial de acción distingue todos los colores","OPCION_C":"La vía activada informa la modalidad sensitiva","OPCION_D":"Solo los receptores de dolor tienen conexiones específicas","RESPUESTA_CORRECTA":"C","EXPLICACION":"El encéfalo interpreta una modalidad según las vías y conexiones que reciben la señal.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Cómo puede codificarse una mayor intensidad de estímulo?","OPCION_A":"Mayor amplitud obligatoria de cada potencial de acción","OPCION_B":"Conversión de todos los estímulos en dolor","OPCION_C":"Desaparición de todos los campos receptivos","OPCION_D":"Mayor frecuencia de descarga y reclutamiento de receptores","RESPUESTA_CORRECTA":"D","EXPLICACION":"La intensidad se refleja en patrones de actividad, no en aumentar indefinidamente la amplitud del potencial de acción.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué es un campo receptivo?","OPCION_A":"Región donde un estímulo modifica la actividad de una neurona sensitiva","OPCION_B":"Área que solo contiene neuronas motoras","OPCION_C":"Cámara donde se aloja el humor acuoso","OPCION_D":"Región vascular sin terminaciones sensitivas","RESPUESTA_CORRECTA":"A","EXPLICACION":"Cada neurona recibe información de una zona definida; el tamaño de esa zona afecta la localización.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué receptor responde intensamente al inicio y luego reduce con rapidez su descarga?","OPCION_A":"Tónico de adaptación lenta","OPCION_B":"Fásico","OPCION_C":"Motor somático","OPCION_D":"Efector glandular","RESPUESTA_CORRECTA":"B","EXPLICACION":"La adaptación rápida permite detectar cambios, inicio o cese de un estímulo.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué receptor mantiene mejor información de un estímulo sostenido?","OPCION_A":"Fásico de adaptación muy rápida","OPCION_B":"Exclusivamente un receptor piloso","OPCION_C":"Tónico","OPCION_D":"Exclusivamente un fotorreceptor de la fóvea","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los receptores tónicos se adaptan lentamente y mantienen actividad durante estímulos persistentes.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué clase de receptor responde a deformación física como presión o estiramiento?","OPCION_A":"Fotorreceptor","OPCION_B":"Quimiorreceptor exclusivamente","OPCION_C":"Termorreceptor exclusivamente","OPCION_D":"Mecanorreceptor","RESPUESTA_CORRECTA":"D","EXPLICACION":"La deformación mecánica modifica la actividad de receptores táctiles, auditivos, vestibulares y propioceptivos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"611-614"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué receptores cutáneos incluyen detectores de temperatura y nocicepción?","OPCION_A":"Únicamente corpúsculos de Pacini","OPCION_B":"Terminaciones nerviosas libres","OPCION_C":"Únicamente botones gustativos","OPCION_D":"Únicamente conos retinianos","RESPUESTA_CORRECTA":"B","EXPLICACION":"Las terminaciones libres detectan varias modalidades y no están rodeadas de una cápsula conjuntiva especializada.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué receptor se asocia con tacto sostenido y reconocimiento de bordes?","OPCION_A":"Órgano tendinoso de Golgi","OPCION_B":"Célula ciliada coclear","OPCION_C":"Disco de Merkel","OPCION_D":"Bastón retiniano","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los discos táctiles de Merkel presentan adaptación lenta y contribuyen a reconocer detalles del contacto.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué receptor está especialmente relacionado con tacto ligero en piel sin pelo?","OPCION_A":"Receptor olfativo","OPCION_B":"Nociceptor visceral exclusivamente","OPCION_C":"Fotorreceptor","OPCION_D":"Corpúsculo de Meissner","RESPUESTA_CORRECTA":"D","EXPLICACION":"Meissner es un mecanorreceptor encapsulado de adaptación rápida presente en piel glabra sensible.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué receptor está especialmente adaptado a vibración y cambios de presión profunda?","OPCION_A":"Corpúsculo de Pacini","OPCION_B":"Botón gustativo","OPCION_C":"Célula olfativa","OPCION_D":"Cono retiniano","RESPUESTA_CORRECTA":"A","EXPLICACION":"La cápsula laminar de Pacini favorece la respuesta a cambios rápidos de deformación.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué cambio detectan los receptores asociados a folículos pilosos?","OPCION_A":"Presión parcial de oxígeno sanguíneo","OPCION_B":"Movimiento del pelo","OPCION_C":"Longitud de onda visible","OPCION_D":"Concentración de glucosa en saliva","RESPUESTA_CORRECTA":"B","EXPLICACION":"El desplazamiento del pelo deforma las terminaciones sensitivas alrededor del folículo.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué informa principalmente el huso muscular?","OPCION_A":"Tensión exclusiva de la hemoglobina","OPCION_B":"Posición del cristalino","OPCION_C":"Longitud muscular y cambios de estiramiento","OPCION_D":"Concentración de sodio plasmático","RESPUESTA_CORRECTA":"C","EXPLICACION":"El huso es un propioceptor situado en el músculo, sensible a longitud y velocidad de estiramiento.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué informa principalmente el órgano tendinoso de Golgi?","OPCION_A":"Intensidad luminosa sobre la retina","OPCION_B":"Presión del humor acuoso","OPCION_C":"Frecuencia del sonido en la cóclea","OPCION_D":"Tensión desarrollada en el tendón","RESPUESTA_CORRECTA":"D","EXPLICACION":"El órgano tendinoso detecta la tensión transmitida por el músculo al tendón.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Por qué las puntas de los dedos discriminan dos puntos mejor que muchas zonas de la espalda?","OPCION_A":"Tienen campos receptivos más pequeños y alta densidad sensitiva","OPCION_B":"Sus potenciales de acción tienen amplitud ilimitada","OPCION_C":"Carecen de receptores encapsulados","OPCION_D":"Reciben únicamente señales motoras","RESPUESTA_CORRECTA":"A","EXPLICACION":"Campos pequeños y mayor representación sensitiva permiten localizar contactos próximos con mayor precisión.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"613-616"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué detectan los nociceptores?","OPCION_A":"Solo sabores dulces","OPCION_B":"Solo colores de onda corta","OPCION_C":"Estímulos potencialmente dañinos para los tejidos","OPCION_D":"Solo posición de las articulaciones sin lesión","RESPUESTA_CORRECTA":"C","EXPLICACION":"La nocicepción inicia señales protectoras frente a estímulos nocivos.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué fibras se relacionan con dolor rápido y relativamente bien localizado?","OPCION_A":"C no mielinizadas exclusivamente","OPCION_B":"Fibras motoras alfa exclusivamente","OPCION_C":"Axones de células ganglionares retinianas","OPCION_D":"A delta","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las fibras A delta son mielinizadas y conducen más rápido que las fibras C.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué fibras participan especialmente en dolor lento, persistente y difuso?","OPCION_A":"C","OPCION_B":"A delta exclusivamente","OPCION_C":"Motoras somáticas exclusivamente","OPCION_D":"Fibras del nervio óptico exclusivamente","RESPUESTA_CORRECTA":"A","EXPLICACION":"Las fibras C son amielínicas y contribuyen al componente lento de la señal dolorosa.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué explica una parte del dolor referido?","OPCION_A":"Movimiento de los receptores desde una víscera a la piel","OPCION_B":"Convergencia de aferencias viscerales y somáticas sobre vías centrales","OPCION_C":"Transformación de un nervio motor en un vaso","OPCION_D":"Desaparición de la médula espinal","RESPUESTA_CORRECTA":"B","EXPLICACION":"El encéfalo puede atribuir a un territorio somático señales procedentes de una víscera.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿En qué región medular ocurre un relevo y modulación importantes del dolor?","OPCION_A":"Asta anterior exclusivamente","OPCION_B":"Conducto ependimario como única vía sináptica","OPCION_C":"Asta posterior","OPCION_D":"Raíz anterior exclusivamente","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las aferencias nociceptivas establecen conexiones en circuitos del asta posterior.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué péptidos participan en inhibición de señales dolorosas?","OPCION_A":"Hemoglobinas","OPCION_B":"Fibrinas","OPCION_C":"Transferrinas","OPCION_D":"Encefalinas","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las encefalinas son opioides endógenos que pueden reducir la transmisión nociceptiva.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Cómo pueden las vías descendentes modificar el dolor?","OPCION_A":"Inhibiendo la transmisión en circuitos espinales","OPCION_B":"Cerrando físicamente todas las arterias cerebrales","OPCION_C":"Transformando receptores en músculos","OPCION_D":"Aumentando necesariamente la amplitud de todos los potenciales de acción","RESPUESTA_CORRECTA":"A","EXPLICACION":"Circuitos del encéfalo y tronco encefálico influyen en el procesamiento medular del dolor.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué describe la teoría de compuerta aplicada al dolor?","OPCION_A":"El dolor viaja por una válvula vascular anatómica","OPCION_B":"La actividad de otras aferencias puede modular su transmisión espinal","OPCION_C":"Toda lesión produce exactamente la misma experiencia dolorosa","OPCION_D":"El tacto elimina de forma permanente cualquier lesión","RESPUESTA_CORRECTA":"B","EXPLICACION":"La interacción entre circuitos sensitivos puede inhibir o facilitar transmisión; no repara por sí misma el tejido lesionado.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"616-619"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué condición facilita que una sustancia estimule las células gustativas?","OPCION_A":"Estar exclusivamente en estado gaseoso seco","OPCION_B":"Ser siempre insoluble en agua","OPCION_C":"Atravesar primero la retina","OPCION_D":"Estar disuelta en saliva","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las moléculas o iones disueltos alcanzan las superficies receptoras a través del poro gustativo.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué diferencia un botón gustativo de una papila lingual?","OPCION_A":"El botón es un conjunto receptor y la papila una proyección de la mucosa","OPCION_B":"Ambos son exactamente el mismo órgano completo","OPCION_C":"El botón es siempre visible a simple vista y la papila nunca","OPCION_D":"La papila es un axón y el botón un tendón","RESPUESTA_CORRECTA":"A","EXPLICACION":"Algunas papilas contienen botones gustativos, pero son estructuras anatómicas de distinto nivel.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué papilas cumplen sobre todo una función mecánica y carecen de botones gustativos?","OPCION_A":"Fungiformes","OPCION_B":"Filiformes","OPCION_C":"Valadas","OPCION_D":"Foliadas","RESPUESTA_CORRECTA":"B","EXPLICACION":"Las papilas filiformes contribuyen a la textura y manejo mecánico del alimento.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué grupo contiene las cinco modalidades gustativas principales?","OPCION_A":"Dulce, frío, picante, presión y amargo","OPCION_B":"Rojo, verde, azul, salado y ácido","OPCION_C":"Dulce, salado, ácido, amargo y umami","OPCION_D":"Tacto, dolor, vibración, calor y umami","RESPUESTA_CORRECTA":"C","EXPLICACION":"El picante y la temperatura añaden sensaciones somáticas, pero no son sabores básicos en esta clasificación.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué estímulo se relaciona directamente con el sabor ácido?","OPCION_A":"Únicamente fotones","OPCION_B":"Únicamente estiramiento muscular","OPCION_C":"Ausencia total de moléculas en saliva","OPCION_D":"Iones hidrógeno","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los ácidos aportan protones que participan en la transducción de la modalidad ácida.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué sustancia se asocia con la modalidad umami?","OPCION_A":"Glutamato","OPCION_B":"Hemoglobina","OPCION_C":"Fibrina","OPCION_D":"Rodopsina","RESPUESTA_CORRECTA":"A","EXPLICACION":"El umami responde a ciertos aminoácidos y se vincula con la cualidad sabrosa de alimentos proteicos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué pares craneales conducen información gustativa?","OPCION_A":"II, III y IV","OPCION_B":"VII, IX y X","OPCION_C":"III, IV y VI exclusivamente","OPCION_D":"XI y XII exclusivamente","RESPUESTA_CORRECTA":"B","EXPLICACION":"Facial, glosofaríngeo y vago recogen gusto de distintos territorios orofaríngeos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Por qué el sabor percibido de una comida disminuye al bloquearse el olfato?","OPCION_A":"Todos los botones gustativos se destruyen de inmediato","OPCION_B":"La lengua deja de tener mecanorreceptores","OPCION_C":"El sabor integra gusto y olfacción además de otras sensaciones","OPCION_D":"El nervio óptico sustituye al facial","RESPUESTA_CORRECTA":"C","EXPLICACION":"La percepción alimentaria combina vías gustativas, olfatorias y somatosensitivas.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"619-622"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Dónde se localiza principalmente el epitelio olfatorio?","OPCION_A":"Región superior de la cavidad nasal","OPCION_B":"Conducto auditivo externo","OPCION_C":"Superficie del cristalino","OPCION_D":"Papilas filiformes de la lengua","RESPUESTA_CORRECTA":"A","EXPLICACION":"Su localización favorece el contacto de odorantes con receptores en el techo nasal.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"621-624"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué tipo de célula es el receptor olfatorio primario?","OPCION_A":"Eritrocito","OPCION_B":"Neurona bipolar","OPCION_C":"Célula muscular lisa","OPCION_D":"Queratinocito superficial","RESPUESTA_CORRECTA":"B","EXPLICACION":"La célula olfatoria es una neurona receptora con prolongaciones periférica y central.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"621-624"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Dónde se unen los odorantes a los receptores de la neurona olfatoria?","OPCION_A":"Axón del nervio óptico","OPCION_B":"Membrana basilar coclear","OPCION_C":"Cilios expuestos al moco","OPCION_D":"Ligamento suspensorio del cristalino","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las moléculas se disuelven en el moco y alcanzan receptores de las membranas ciliares.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"621-624"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué estructura ósea atraviesan los axones de las neuronas olfatorias?","OPCION_A":"Conducto óptico del esfenoides","OPCION_B":"Agujero oval exclusivamente","OPCION_C":"Conducto carotídeo exclusivamente","OPCION_D":"Lámina cribosa del etmoides","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los filetes olfatorios cruzan la lámina cribosa para alcanzar el bulbo olfatorio.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"621-624"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿En qué estructura se agrupan las primeras conexiones del receptor olfatorio en el bulbo?","OPCION_A":"Glomérulos olfatorios","OPCION_B":"Corpúsculos renales","OPCION_C":"Botones gustativos","OPCION_D":"Corpúsculos de Pacini","RESPUESTA_CORRECTA":"A","EXPLICACION":"Los glomérulos organizan conexiones entre axones receptores y células del bulbo.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 16","PAGINAS_PDF":"621-624"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","PREGUNTA":"¿Qué par craneal se relaciona con el olfato?","OPCION_A":"II","OPCION_B":"I","OPCION_C":"V exclusivamente","OPCION_D":"VIII","RESPUESTA_CORRECTA":"B","EXPLICACION":"El nervio olfa