INSERT INTO public.evaluacion_preguntas(id,evaluacion_id,tipo,texto,opciones,orden,puntos,temporizador)
SELECT p.id,p.evaluacion_id,p.tipo,p.texto,p.opciones,p.orden,p.puntos,p.temporizador FROM jsonb_to_recordset('[{"id":"ba58e297-1b19-5d03-939a-6df6688b8a3c","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué es un campo receptivo?","opciones":[{"text":"Región donde un estímulo modifica la actividad de una neurona sensitiva","correct":true,"color":"ac-blue"},{"text":"Área que solo contiene neuronas motoras","correct":false,"color":"ac-pink"},{"text":"Cámara donde se aloja el humor acuoso","correct":false,"color":"ac-yellow"},{"text":"Región vascular sin terminaciones sensitivas","correct":false,"color":"ac-green"}],"orden":1,"puntos":1,"temporizador":60},{"id":"e14fdad4-a269-5f08-b809-d81c27881bad","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué receptor responde intensamente al inicio y luego reduce con rapidez su descarga?","opciones":[{"text":"Tónico de adaptación lenta","correct":false,"color":"ac-blue"},{"text":"Fásico","correct":true,"color":"ac-pink"},{"text":"Motor somático","correct":false,"color":"ac-yellow"},{"text":"Efector glandular","correct":false,"color":"ac-green"}],"orden":2,"puntos":1,"temporizador":60},{"id":"7ce3eedf-8d60-58ba-ab25-56933dcaa955","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué receptor mantiene mejor información de un estímulo sostenido?","opciones":[{"text":"Fásico de adaptación muy rápida","correct":false,"color":"ac-blue"},{"text":"Exclusivamente un receptor piloso","correct":false,"color":"ac-pink"},{"text":"Tónico","correct":true,"color":"ac-yellow"},{"text":"Exclusivamente un fotorreceptor de la fóvea","correct":false,"color":"ac-green"}],"orden":3,"puntos":1,"temporizador":60},{"id":"d628d3d8-637a-516b-9342-95565c7e03cf","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué cambio detectan los receptores asociados a folículos pilosos?","opciones":[{"text":"Presión parcial de oxígeno sanguíneo","correct":false,"color":"ac-blue"},{"text":"Movimiento del pelo","correct":true,"color":"ac-pink"},{"text":"Longitud de onda visible","correct":false,"color":"ac-yellow"},{"text":"Concentración de glucosa en saliva","correct":false,"color":"ac-green"}],"orden":4,"puntos":1,"temporizador":60},{"id":"3af1414d-c6a7-54af-b166-23b82817d8ea","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué informa principalmente el huso muscular?","opciones":[{"text":"Tensión exclusiva de la hemoglobina","correct":false,"color":"ac-blue"},{"text":"Posición del cristalino","correct":false,"color":"ac-pink"},{"text":"Longitud muscular y cambios de estiramiento","correct":true,"color":"ac-yellow"},{"text":"Concentración de sodio plasmático","correct":false,"color":"ac-green"}],"orden":5,"puntos":1,"temporizador":60},{"id":"f5eb4995-a6bf-5039-a098-95d014867d4a","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué informa principalmente el órgano tendinoso de Golgi?","opciones":[{"text":"Intensidad luminosa sobre la retina","correct":false,"color":"ac-blue"},{"text":"Presión del humor acuoso","correct":false,"color":"ac-pink"},{"text":"Frecuencia del sonido en la cóclea","correct":false,"color":"ac-yellow"},{"text":"Tensión desarrollada en el tendón","correct":true,"color":"ac-green"}],"orden":6,"puntos":1,"temporizador":60},{"id":"4d8af903-c6cf-5cd9-9c56-3d1fd0ba1c22","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿En qué región medular ocurre un relevo y modulación importantes del dolor?","opciones":[{"text":"Asta anterior exclusivamente","correct":false,"color":"ac-blue"},{"text":"Conducto ependimario como única vía sináptica","correct":false,"color":"ac-pink"},{"text":"Asta posterior","correct":true,"color":"ac-yellow"},{"text":"Raíz anterior exclusivamente","correct":false,"color":"ac-green"}],"orden":7,"puntos":1,"temporizador":60},{"id":"5bccd87e-b1d5-5ec5-b571-3ac8e2dae4a8","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué péptidos participan en inhibición de señales dolorosas?","opciones":[{"text":"Hemoglobinas","correct":false,"color":"ac-blue"},{"text":"Fibrinas","correct":false,"color":"ac-pink"},{"text":"Transferrinas","correct":false,"color":"ac-yellow"},{"text":"Encefalinas","correct":true,"color":"ac-green"}],"orden":8,"puntos":1,"temporizador":60},{"id":"ab8b11a5-0768-5db5-8622-7f52f78ee798","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Cómo pueden las vías descendentes modificar el dolor?","opciones":[{"text":"Inhibiendo la transmisión en circuitos espinales","correct":true,"color":"ac-blue"},{"text":"Cerrando físicamente todas las arterias cerebrales","correct":false,"color":"ac-pink"},{"text":"Transformando receptores en músculos","correct":false,"color":"ac-yellow"},{"text":"Aumentando necesariamente la amplitud de todos los potenciales de acción","correct":false,"color":"ac-green"}],"orden":9,"puntos":1,"temporizador":60},{"id":"69525ef7-eda4-5484-aafd-9c8331cbd9f8","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué estímulo se relaciona directamente con el sabor ácido?","opciones":[{"text":"Únicamente fotones","correct":false,"color":"ac-blue"},{"text":"Únicamente estiramiento muscular","correct":false,"color":"ac-pink"},{"text":"Ausencia total de moléculas en saliva","correct":false,"color":"ac-yellow"},{"text":"Iones hidrógeno","correct":true,"color":"ac-green"}],"orden":10,"puntos":1,"temporizador":60},{"id":"04be5c6e-6959-583d-9d18-294605bcf245","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué sustancia se asocia con la modalidad umami?","opciones":[{"text":"Glutamato","correct":true,"color":"ac-blue"},{"text":"Hemoglobina","correct":false,"color":"ac-pink"},{"text":"Fibrina","correct":false,"color":"ac-yellow"},{"text":"Rodopsina","correct":false,"color":"ac-green"}],"orden":11,"puntos":1,"temporizador":60},{"id":"54ed206a-aa79-5e34-94d6-4e58c05e39cc","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué pares craneales conducen información gustativa?","opciones":[{"text":"II, III y IV","correct":false,"color":"ac-blue"},{"text":"VII, IX y X","correct":true,"color":"ac-pink"},{"text":"III, IV y VI exclusivamente","correct":false,"color":"ac-yellow"},{"text":"XI y XII exclusivamente","correct":false,"color":"ac-green"}],"orden":12,"puntos":1,"temporizador":60},{"id":"0d91b59f-fb01-52d1-b2aa-7740fd9d777b","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿En qué estructura se agrupan las primeras conexiones del receptor olfatorio en el bulbo?","opciones":[{"text":"Glomérulos olfatorios","correct":true,"color":"ac-blue"},{"text":"Corpúsculos renales","correct":false,"color":"ac-pink"},{"text":"Botones gustativos","correct":false,"color":"ac-yellow"},{"text":"Corpúsculos de Pacini","correct":false,"color":"ac-green"}],"orden":13,"puntos":1,"temporizador":60},{"id":"9b90c6e1-da14-5d8a-9f95-4a4480e0be0c","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué par craneal se relaciona con el olfato?","opciones":[{"text":"II","correct":false,"color":"ac-blue"},{"text":"I","correct":true,"color":"ac-pink"},{"text":"V exclusivamente","correct":false,"color":"ac-yellow"},{"text":"VIII","correct":false,"color":"ac-green"}],"orden":14,"puntos":1,"temporizador":60},{"id":"a3590f9a-c652-505f-ac17-01dcc9b47177","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué característica distingue la vía inicial hacia la corteza olfatoria primaria?","opciones":[{"text":"No utiliza neuronas","correct":false,"color":"ac-blue"},{"text":"Solo pasa por el cerebelo","correct":false,"color":"ac-pink"},{"text":"No requiere relevo talámico previo","correct":true,"color":"ac-yellow"},{"text":"Utiliza obligatoriamente el nervio óptico","correct":false,"color":"ac-green"}],"orden":15,"puntos":1,"temporizador":60},{"id":"c1ad61d9-941c-5bcd-bb90-f152b526c684","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué estructura del oído interno se relaciona principalmente con la audición?","opciones":[{"text":"Utrículo","correct":false,"color":"ac-blue"},{"text":"Cóclea","correct":true,"color":"ac-pink"},{"text":"Sáculo exclusivamente","correct":false,"color":"ac-yellow"},{"text":"Conductos semicirculares exclusivamente","correct":false,"color":"ac-green"}],"orden":16,"puntos":1,"temporizador":60},{"id":"e58523eb-ec0d-5f46-a3fa-8312f98666b2","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué líquido ocupa el interior del laberinto membranoso?","opciones":[{"text":"Perilinfa","correct":false,"color":"ac-blue"},{"text":"Humor acuoso","correct":false,"color":"ac-pink"},{"text":"Endolinfa","correct":true,"color":"ac-yellow"},{"text":"Líquido sinovial","correct":false,"color":"ac-green"}],"orden":17,"puntos":1,"temporizador":60},{"id":"b6570611-63e0-580b-b636-63fbb5c6bce6","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué líquido contienen las escalas vestibular y timpánica de la cóclea?","opciones":[{"text":"Endolinfa","correct":false,"color":"ac-blue"},{"text":"Humor vítreo","correct":false,"color":"ac-pink"},{"text":"Plasma sanguíneo sin modificaciones","correct":false,"color":"ac-yellow"},{"text":"Perilinfa","correct":true,"color":"ac-green"}],"orden":18,"puntos":1,"temporizador":60},{"id":"837b4bba-5ba4-5190-be68-f15e14818800","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué ion entra desde la endolinfa y contribuye a despolarizar células ciliadas?","opciones":[{"text":"Hierro","correct":false,"color":"ac-blue"},{"text":"Yodo","correct":false,"color":"ac-pink"},{"text":"Potasio","correct":true,"color":"ac-yellow"},{"text":"Cobre","correct":false,"color":"ac-green"}],"orden":19,"puntos":1,"temporizador":60},{"id":"d6c54745-8db0-5bdd-8d3a-03640b4c7400","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué región de la membrana basilar responde mejor a frecuencias altas?","opciones":[{"text":"Ápice coclear","correct":false,"color":"ac-blue"},{"text":"Utrículo exclusivamente","correct":false,"color":"ac-pink"},{"text":"Sáculo exclusivamente","correct":false,"color":"ac-yellow"},{"text":"Base coclear","correct":true,"color":"ac-green"}],"orden":20,"puntos":1,"temporizador":60},{"id":"3e62f20f-66cd-595d-98c8-5b3b7cc7d3b4","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué función destacan las células ciliadas externas?","opciones":[{"text":"Amplificar y afinar la respuesta mecánica coclear","correct":true,"color":"ac-blue"},{"text":"Producir anticuerpos en la endolinfa","correct":false,"color":"ac-pink"},{"text":"Formar los tres huesecillos del oído","correct":false,"color":"ac-yellow"},{"text":"Secretar humor acuoso","correct":false,"color":"ac-green"}],"orden":21,"puntos":1,"temporizador":60},{"id":"4a08ce1b-f8f6-58f6-8589-dbf50d390e9a","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué estructura gelatinosa se deforma sobre las células de la cresta ampular?","opciones":[{"text":"Membrana timpánica","correct":false,"color":"ac-blue"},{"text":"Cápsula del cristalino","correct":false,"color":"ac-pink"},{"text":"Membrana pleural","correct":false,"color":"ac-yellow"},{"text":"Cúpula","correct":true,"color":"ac-green"}],"orden":22,"puntos":1,"temporizador":60},{"id":"e7819dae-2c04-5aa2-b9c4-816b0a7c6792","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué efecto suele tener la deflexión de estereocilios hacia el cinocilio vestibular?","opciones":[{"text":"Aumento de la despolarización y descarga aferente","correct":true,"color":"ac-blue"},{"text":"Inhibición obligatoria sin excepción","correct":false,"color":"ac-pink"},{"text":"Generación de fibrina","correct":false,"color":"ac-yellow"},{"text":"Destrucción inmediata del receptor","correct":false,"color":"ac-green"}],"orden":23,"puntos":1,"temporizador":60},{"id":"f8a59365-c73c-5530-9f31-0cc81b897109","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Cuál es la función principal del reflejo vestibuloocular?","opciones":[{"text":"Cambiar el grupo sanguíneo del ojo","correct":false,"color":"ac-blue"},{"text":"Estabilizar la imagen retiniana durante movimientos de la cabeza","correct":true,"color":"ac-pink"},{"text":"Producir lágrimas solo al dormir","correct":false,"color":"ac-yellow"},{"text":"Ajustar exclusivamente la presión del oído medio","correct":false,"color":"ac-green"}],"orden":24,"puntos":1,"temporizador":60},{"id":"772fe026-0e15-5e7a-8b44-551175364050","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué ocurre con el cristalino al acomodar para visión cercana?","opciones":[{"text":"Se hace más convexo al disminuir la tensión zonular","correct":true,"color":"ac-blue"},{"text":"Se aplana por contracción del músculo ciliar","correct":false,"color":"ac-pink"},{"text":"Se vuelve opaco necesariamente","correct":false,"color":"ac-yellow"},{"text":"Se desplaza al interior del nervio óptico","correct":false,"color":"ac-green"}],"orden":25,"puntos":1,"temporizador":60},{"id":"78e3b639-eef0-5b10-965e-41daf779c62b","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué combinación integra la respuesta de visión cercana?","opciones":[{"text":"Divergencia, dilatación pupilar y pérdida del cristalino","correct":false,"color":"ac-blue"},{"text":"Convergencia, constricción pupilar y acomodación","correct":true,"color":"ac-pink"},{"text":"Convergencia, opacidad corneal y ausencia de refracción","correct":false,"color":"ac-yellow"},{"text":"Contracción del tímpano, miosis y olfacción","correct":false,"color":"ac-green"}],"orden":26,"puntos":1,"temporizador":60},{"id":"e8a01e0c-42e0-5898-b44c-9f980928f1d7","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Dónde se enfoca la imagen de un objeto lejano en un ojo miope no corregido?","opciones":[{"text":"Detrás de la retina","correct":false,"color":"ac-blue"},{"text":"En el conducto nasolagrimal","correct":false,"color":"ac-pink"},{"text":"Delante de la retina","correct":true,"color":"ac-yellow"},{"text":"En la cámara anterior exclusivamente","correct":false,"color":"ac-green"}],"orden":27,"puntos":1,"temporizador":60},{"id":"58ce8bd9-1d81-5439-aab0-a322d6a2311c","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué efecto tiene la luz sobre el potencial del bastón durante la fototransducción?","opciones":[{"text":"Despolarización por aumento indefinido de cGMP","correct":false,"color":"ac-blue"},{"text":"Hiperpolarización al disminuir cGMP y cerrarse canales","correct":true,"color":"ac-pink"},{"text":"Ningún cambio eléctrico o químico","correct":false,"color":"ac-yellow"},{"text":"Conversión del bastón en célula ganglionar","correct":false,"color":"ac-green"}],"orden":28,"puntos":1,"temporizador":60},{"id":"05ead1ed-5fd7-5f0d-af55-0d292f806723","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué axones forman el nervio óptico?","opciones":[{"text":"Los de bastones directamente","correct":false,"color":"ac-blue"},{"text":"Los de conos directamente","correct":false,"color":"ac-pink"},{"text":"Los de células ganglionares retinianas","correct":true,"color":"ac-yellow"},{"text":"Los de músculos extraoculares","correct":false,"color":"ac-green"}],"orden":29,"puntos":1,"temporizador":60},{"id":"6e6fc89b-c475-5167-ac1e-fe03eccb9e9d","evaluacion_id":"9938a92b-91ac-5ae7-97b8-a0de2c313a1c","tipo":"mc","texto":"¿Qué fibras cruzan normalmente en el quiasma óptico?","opciones":[{"text":"Todas las fibras de ambos nervios ópticos","correct":false,"color":"ac-blue"},{"text":"Solo fibras de hemirretinas temporales","correct":false,"color":"ac-pink"},{"text":"Únicamente fibras motoras del iris","correct":false,"color":"ac-yellow"},{"text":"Las procedentes de hemirretinas nasales","correct":true,"color":"ac-green"}],"orden":30,"puntos":1,"temporizador":60}]'::jsonb) AS p(id uuid,evaluacion_id uuid,tipo text,texto text,opciones jsonb,orden int,puntos int,temporizador int) ON CONFLICT(id) DO NOTHING;
COMMIT;
